package com.project.system.service;
import java.util.*;import java.time.*;import java.math.BigDecimal;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import com.fasterxml.jackson.databind.*;
@Service public class MerchantApiService{
 @Autowired private JdbcTemplate db;@Autowired private WalletService wallets;@Autowired private PlatformTransactionManager manager;private final ObjectMapper json=new ObjectMapper().enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(com.fasterxml.jackson.core.JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
 public void ensure(long merchant){if(merchant==3)throw new IllegalArgumentException("系统测试商户不开放外部接口");if(db.queryForObject("select count(*) from campus_merchant where id=?",Integer.class,merchant)!=1)throw new IllegalArgumentException("商户不存在");db.update("insert ignore into campus_api_credential(merchant_id,public_id,secret) values(?,?,?)",merchant,UUID.randomUUID().toString(),ApiSecurity.secret());}
 public Map<String,Object> config(long merchant){ensure(merchant);return db.queryForMap("select c.merchant_id,m.name,c.public_id,c.enabled,c.allow_recharge,c.allow_pay,c.callback_url,c.updated_at from campus_api_credential c join campus_merchant m on m.id=c.merchant_id where c.merchant_id=?",merchant);}
 public String rotate(long merchant,long actor){ensure(merchant);String secret=ApiSecurity.secret();db.update("update campus_api_credential set secret=?,enabled=0 where merchant_id=?",secret,merchant);log(UUID.randomUUID().toString(),String.valueOf(config(merchant).get("public_id")),null,"ROTATE","SUCCESS","密钥已重置并停用接口；操作人"+actor);return secret;}
 public void configure(long merchant,boolean enabled,boolean recharge,boolean pay,String callback,long actor){ensure(merchant);db.update("update campus_api_credential set enabled=?,allow_recharge=?,allow_pay=?,callback_url='' where merchant_id=?",enabled,recharge,pay,merchant);log(UUID.randomUUID().toString(),String.valueOf(config(merchant).get("public_id")),null,"CONFIG","SUCCESS","接口配置变更；同步响应模式；操作人"+actor);}
 public void log(String trace,String merchant,String order,String action,String code,String message){db.update("insert into campus_api_log(trace_id,public_id,order_no,action,code,message) values(?,?,?,?,?,?)",trace,merchant!=null&&merchant.length()<=36?merchant:null,order!=null&&order.length()<=48?order:null,action==null?"UNKNOWN":action.substring(0,Math.min(32,action.length())),code,message==null?"":message.substring(0,Math.min(300,message.length())));}
 public Map<String,Object> authenticate(String publicId,String timestamp,String nonce,String signature,String path,String raw){if(publicId==null||!publicId.matches("[0-9a-fA-F-]{36}"))throw new IllegalArgumentException("商户标识无效");List<Map<String,Object>> rows=db.queryForList("select c.*,m.name,m.active from campus_api_credential c join campus_merchant m on c.merchant_id=m.id where c.public_id=?",publicId);if(rows.isEmpty())throw new IllegalArgumentException("商户标识不存在");Map<String,Object> c=rows.get(0);if(((Number)c.get("enabled")).intValue()!=1||((Number)c.get("active")).intValue()!=1)throw new IllegalArgumentException("商户或接口未启用");long time;try{time=Long.parseLong(timestamp);}catch(Exception e){throw new IllegalArgumentException("时间戳无效");}long now=Instant.now().getEpochSecond();if(time<now-300||time>now+300)throw new IllegalArgumentException("请求已过期或时钟不一致");if(nonce==null||!nonce.matches("[A-Za-z0-9-]{16,64}"))throw new IllegalArgumentException("随机请求标识无效");if(signature==null||!signature.matches("[a-fA-F0-9]{64}")||!ApiSecurity.equal(ApiSecurity.sign((String)c.get("secret"),timestamp,nonce,path,raw),signature.toLowerCase(Locale.ROOT)))throw new IllegalArgumentException("签名验证失败");try{db.update("insert into campus_api_nonce(public_id,nonce) values(?,?)",publicId,nonce);}catch(org.springframework.dao.DuplicateKeyException e){throw new IllegalArgumentException("重复通讯请求，请更换nonce并查询原订单");}return c;}
 public Map<String,String> parse(String raw,String action){if(raw==null||raw.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>16384)throw new IllegalArgumentException("请求体不能超过16KB");try{JsonNode node=json.readTree(raw);if(node==null||!node.isObject())throw new IllegalArgumentException("请求体必须是JSON对象");Set<String> allowed=new HashSet<>();if(action.equals("balance"))allowed.addAll(Arrays.asList("merchantId","cardNo"));else if(action.equals("query"))allowed.addAll(Arrays.asList("merchantId","campusOrderNo","merchantSerialNo"));else allowed.addAll(Arrays.asList("merchantId","merchantName","merchantSerialNo","amount","occurredAt","location","cardNo","description"));Map<String,String> out=new TreeMap<>();Iterator<Map.Entry<String,JsonNode>> it=node.fields();while(it.hasNext()){Map.Entry<String,JsonNode> x=it.next();if(!allowed.contains(x.getKey())||!x.getValue().isTextual())throw new IllegalArgumentException("未知字段或字段不是字符串："+x.getKey());out.put(x.getKey(),x.getValue().asText());}return out;}catch(java.io.IOException e){throw new IllegalArgumentException("JSON格式无效");}}
 private String required(Map<String,String> p,String key,int max){String v=p.get(key);if(v==null||v.trim().isEmpty()||v.length()>max)throw new IllegalArgumentException("缺失或无效字段："+key);return v;}
 private String canonical(Map<String,String> c){Map<String,String> copy=new TreeMap<>(c);copy.remove("orderNo");copy.remove("localSerialNo");try{return json.writeValueAsString(copy);}catch(Exception e){throw new IllegalStateException(e);}}
 private void validate(Map<String,Object> c,Map<String,String> p){if(!c.get("public_id").equals(required(p,"merchantId",36))||!c.get("name").equals(required(p,"merchantName",100)))throw new IllegalArgumentException("商户ID或名称不匹配");if(!required(p,"requestId",64).matches("[A-Za-z0-9_-]{8,64}"))throw new IllegalArgumentException("requestId格式无效");String kind=required(p,"tradeType",12);if(!Arrays.asList("RECHARGE","PAY").contains(kind))throw new IllegalArgumentException("交易类型仅支持RECHARGE或PAY");if(((Number)c.get(kind.equals("PAY")?"allow_pay":"allow_recharge")).intValue()!=1)throw new IllegalArgumentException("商户未获得此交易类型授权");String amount=required(p,"amount",16);if(!amount.matches("[0-9]{1,6}(\\.[0-9]{1,2})?"))throw new IllegalArgumentException("金额格式无效");BigDecimal money=new BigDecimal(amount);if(money.signum()<=0||money.compareTo(new BigDecimal("100000"))>0)throw new IllegalArgumentException("金额必须在0.01至100000元之间");required(p,"location",200);required(p,"description",500);if(!required(p,"cardNo",34).matches("CC[A-F0-9]{32}"))throw new IllegalArgumentException("卡号格式无效");try{OffsetDateTime occurred=OffsetDateTime.parse(required(p,"occurredAt",40));if(Math.abs(Duration.between(occurred.toInstant(),Instant.now()).getSeconds())>86400)throw new IllegalArgumentException("业务发生时间须在当前时间前后24小时内");}catch(java.time.format.DateTimeParseException e){throw new IllegalArgumentException("occurredAt须为带时区的ISO8601时间");}}
 public Map<String,Object> create(Map<String,Object> c,Map<String,String> p){validate(c,p);long merchant=((Number)c.get("merchant_id")).longValue();String hash=ApiSecurity.hash(canonical(p));return new TransactionTemplate(manager).execute(tx->{db.queryForObject("select merchant_id from campus_api_credential where merchant_id=? for update",Long.class,merchant);List<Map<String,Object>> old=db.queryForList("select * from campus_api_order where merchant_id=? and request_id=?",merchant,p.get("requestId"));if(!old.isEmpty()){if(!hash.equals(old.get(0).get("payload_hash")))throw new IllegalArgumentException("requestId已用于不同交易");return result(old.get(0));}String number="DD"+java.time.format.DateTimeFormatter.ofPattern("yyyyMMddHHmmss").withZone(ZoneId.of("Asia/Shanghai")).format(Instant.now())+UUID.randomUUID().toString().replace("-","").substring(0,20).toUpperCase(Locale.ROOT);java.sql.Timestamp occurred=java.sql.Timestamp.from(OffsetDateTime.parse(p.get("occurredAt")).toInstant());db.update("insert into campus_api_order(order_no,merchant_id,request_id,payload_hash,trade_type,card_no,amount,occurred_at,location,description) values(?,?,?,?,?,?,?,?,?,?)",number,merchant,p.get("requestId"),hash,p.get("tradeType"),p.get("cardNo"),new BigDecimal(p.get("amount")),occurred,p.get("location"),p.get("description"));return result(order(merchant,number,false));});}
 private Map<String,Object> order(long merchant,String number,boolean lock){List<Map<String,Object>> rows=db.queryForList("select * from campus_api_order where merchant_id=? and order_no=?"+(lock?" for update":""),merchant,number);if(rows.isEmpty())throw new IllegalArgumentException("订单不存在或不属于当前商户");return rows.get(0);}
 public Map<String,Object> query(Map<String,Object> c,Map<String,String> p){if(!c.get("public_id").equals(required(p,"merchantId",36)))throw new IllegalArgumentException("商户标识不匹配");return result(order(((Number)c.get("merchant_id")).longValue(),required(p,"orderNo",48),false));}
 public Map<String,Object> execute(Map<String,Object> c,Map<String,String> p){long merchant=((Number)c.get("merchant_id")).longValue();String number=required(p,"orderNo",48),serial=required(p,"localSerialNo",64);if(!serial.matches("[A-Za-z0-9_-]{8,64}"))throw new IllegalArgumentException("localSerialNo格式无效");String hash=ApiSecurity.hash(canonical(p));Map<String,Object> existing=order(merchant,number,false);if(!hash.equals(existing.get("payload_hash")))throw new IllegalArgumentException("交易参数与申请订单时不一致");if(!"NEW".equals(existing.get("status"))){if(!serial.equals(existing.get("local_serial")))throw new IllegalArgumentException("订单已使用其他本地流水号完成");return result(existing);}validate(c,p);
 try{return new TransactionTemplate(manager).execute(tx->{Map<String,Object> o=order(merchant,number,true);if(!"NEW".equals(o.get("status"))){if(!serial.equals(o.get("local_serial")))throw new IllegalArgumentException("订单已使用其他流水号");return result(o);}db.update("update campus_api_order set local_serial=? where id=?",serial,o.get("id"));List<Map<String,Object>> users=db.queryForList("select user_id from campus_card where card_no=?",o.get("card_no"));if(users.size()!=1)throw new IllegalArgumentException("卡号不存在或已注销");long user=((Number)users.get(0).get("user_id")).longValue();db.queryForObject("select user_id from sys_user where user_id=? for update",Long.class,user);if(db.queryForObject("select count(*) from campus_card where card_no=? and user_id=?",Integer.class,o.get("card_no"),user)!=1)throw new IllegalArgumentException("卡片已注销或绑定关系改变");long ledger=wallets.trade(user,(String)o.get("trade_type"),(BigDecimal)o.get("amount"),"PAY".equals(o.get("trade_type"))?merchant:null,null,"API-"+number,0L);if(db.queryForList("select id from campus_merchant where id=? and active=1 for update",merchant).isEmpty())throw new IllegalArgumentException("商户已停用");if("RECHARGE".equals(o.get("trade_type")))db.update("update campus_recharge_order set order_no=? where ledger_id=?",number,ledger);db.update("update campus_api_order set status='SUCCESS',ledger_id=?,completed_at=NOW() where id=?",ledger,o.get("id"));Map<String,Object> completed=order(merchant,number,false);return result(completed);});}catch(RuntimeException error){if(error instanceof org.springframework.dao.DuplicateKeyException)throw new IllegalArgumentException("本地流水号已用于其他订单");String message=error instanceof IllegalArgumentException?error.getMessage():"交易处理失败，资金未入账，请查询订单后重新申请";return new TransactionTemplate(manager).execute(tx->{Map<String,Object> o=order(merchant,number,true);if(!"NEW".equals(o.get("status"))){if(!serial.equals(o.get("local_serial")))throw new IllegalArgumentException("订单已使用其他本地流水号");return result(o);}db.update("update campus_api_order set status='FAILED',local_serial=?,error_message=?,completed_at=NOW() where id=?",serial,message,o.get("id"));Map<String,Object> failed=order(merchant,number,false);return result(failed);});}}
 public Map<String,Object> result(Map<String,Object> o){Map<String,Object> r=new LinkedHashMap<>();r.put("orderNo",o.get("order_no"));r.put("requestId",o.get("request_id"));r.put("localSerialNo",o.get("local_serial"));r.put("tradeType",o.get("trade_type"));r.put("amount",o.get("amount").toString());r.put("status",o.get("status"));r.put("message",o.get("error_message"));r.put("transactionNo",o.get("ledger_id")==null?null:wallets.receipt(((Number)o.get("ledger_id")).longValue()).get("transaction_no"));return r;}
 public Map<String,Object> adminData(long merchant,int page){ensure(merchant);Map<String,Object> r=new LinkedHashMap<>();r.put("config",config(merchant));r.put("total",db.queryForObject("select count(*) from campus_api_order where merchant_id=?",Long.class,merchant));r.put("orders",db.queryForList("select order_no,request_id,local_serial,trade_type,amount,status,occurred_at,location,description,error_message,created_at from campus_api_order where merchant_id=? order by id desc limit 20 offset ?",merchant,(Math.max(1,Math.min(page,100000))-1)*20));r.put("logs",db.queryForList("select trace_id,order_no,action,code,message,created_at from campus_api_log where public_id=? order by id desc limit 30",config(merchant).get("public_id")));return r;}

 private void identity(Map<String,Object> c,Map<String,String> p){if(!c.get("public_id").equals(required(p,"merchantId",36)))throw new IllegalArgumentException("商户标识不匹配");}
 public Map<String,Object> balance(Map<String,Object> c,Map<String,String> p){identity(c,p);String card=required(p,"cardNo",34);List<Map<String,Object>> rows=db.queryForList("select w.balance,w.status wallet_status,u.status user_status from campus_card c join sys_user u on u.user_id=c.user_id join campus_wallet w on w.user_id=u.user_id where c.card_no=? and u.del_flag='0'",card);if(rows.size()!=1)throw new IllegalArgumentException("卡号不存在或已注销");Map<String,Object> row=rows.get(0),r=new LinkedHashMap<>();r.put("cardNo",card);r.put("walletStatus",row.get("wallet_status"));boolean canPay="ACTIVE".equals(row.get("wallet_status"))&&"0".equals(row.get("user_status"));r.put("balance",row.get("balance").toString());r.put("availableBalance",canPay?row.get("balance").toString():"0.00");r.put("canPay",canPay);return r;}
 public Map<String,Object> payment(Map<String,Object> c,Map<String,String> p,String kind){identity(c,p);String serial=required(p,"merchantSerialNo",64);if(!serial.matches("[A-Za-z0-9_-]{8,64}"))throw new IllegalArgumentException("商户流水号须为8至64位字母数字及_-，同一业务重试必须保持不变");Map<String,String> normalized=new TreeMap<>(p);normalized.remove("merchantSerialNo");normalized.put("requestId",serial);normalized.put("tradeType",kind);long merchant=((Number)c.get("merchant_id")).longValue();List<Map<String,Object>> old=db.queryForList("select * from campus_api_order where merchant_id=? and request_id=?",merchant,serial);if(!old.isEmpty()){if(!ApiSecurity.hash(canonical(normalized)).equals(old.get(0).get("payload_hash")))throw new IllegalArgumentException("商户流水号已用于不同的金额、卡号或交易内容");if(!"NEW".equals(old.get(0).get("status")))return paymentResult(old.get(0));}
 Map<String,Object> created=create(c,normalized);String number=(String)created.get("orderNo");normalized.put("orderNo",number);normalized.put("localSerialNo",serial);execute(c,normalized);return paymentResult(order(merchant,number,false));}
 public Map<String,Object> paymentQuery(Map<String,Object> c,Map<String,String> p){identity(c,p);long merchant=((Number)c.get("merchant_id")).longValue();String number=p.get("campusOrderNo"),serial=p.get("merchantSerialNo");if((number==null||number.isEmpty())&&(serial==null||serial.isEmpty()))throw new IllegalArgumentException("请提供商户流水号或一卡通订单号");Map<String,Object> o;if(number!=null&&!number.isEmpty()){o=order(merchant,number,false);if(serial!=null&&!serial.isEmpty()&&!serial.equals(o.get("request_id")))throw new IllegalArgumentException("商户流水号与一卡通订单号不匹配");}else{List<Map<String,Object>> rows=db.queryForList("select * from campus_api_order where merchant_id=? and (request_id=? or local_serial=?)",merchant,serial,serial);if(rows.size()>1)throw new IllegalArgumentException("历史商户流水号存在歧义，请使用一卡通订单号查询");if(rows.isEmpty())throw new IllegalArgumentException("未找到此商户流水号对应的交易");o=rows.get(0);}return paymentResult(o);}
 private Map<String,Object> paymentResult(Map<String,Object> o){Map<String,Object> r=new LinkedHashMap<>();r.put("merchantSerialNo",o.get("local_serial")==null?o.get("request_id"):o.get("local_serial"));r.put("campusOrderNo",o.get("order_no"));r.put("tradeType",o.get("trade_type"));r.put("status","NEW".equals(o.get("status"))?"PROCESSING":o.get("status"));r.put("amount",o.get("amount").toString());r.put("message",o.get("error_message"));r.put("balanceAfter",o.get("ledger_id")==null?null:db.queryForObject("select balance_after from campus_ledger where id=?",java.math.BigDecimal.class,o.get("ledger_id")).toPlainString());return r;}
}
